CREATE OR REPLACE FUNCTION public.slugify_identifier(value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select trim(
    both '-'
    from regexp_replace(
      lower(trim(coalesce(value, ''))),
      '[^a-z0-9]+',
      '-',
      'g'
    )
  );
$function$
;